code='def top_three(products):\n    work=products[:]\n    for i in range(3):\n        best=i\n        for j in range(i+1,len(work)):\n            if work[j].price > work[best].price:\n                best=j\n        work[i],work[best]=work[best],work[i]\n    return work[:3]'
e(16,'b',22,5,'Construct','Construct sortArt() returningfivemostexpensiveartworks,usingselectionsort.',C,['B2.4.3','B2.2.2'],'B',33,'Selectionmaxindex,outer/innerloops,swap,returntop5;assumefiveobjectsneeded.','Construct top_three(products) inPython. Each product has a price attribute andthe list contains atleastthree products. Return three highest-priced product objects in descending price order,using selection sort. Do not modify the supplied list.',pts((1,'Creates a separate working copy andreturns its first three objects.'),(1,'Performs three selection passes over positions0..2.'),(1,'Searches remaining positions for the maximum price.'),(1,'Maintains/updates the selected index correctly.'),(1,'Swaps selected object into the current output position,producing descending order.')),solution=code,code=code,tests='from types import SimpleNamespace\nitems=[SimpleNamespace(price=x) for x in [4,9,1,7,5]];before=items[:]\nassert [x.price for x in top_three(items)]==[9,7,5] and items==before\nassert [x.price for x in top_three([SimpleNamespace(price=x) for x in [3,3,1]])]==[3,3,1]',reason='Retains selectionsort/objects/top-k reasoning;explicitminimumlength avoids sourceunderspecification,Pythoncopyprotectsinput.')
code='def total_fee(products):\n    total=0\n    for product in products:\n        if product.sold:\n            total+=product.price\n    return total*0.12'
